<script setup>
import {ref,reactive,onMounted,watch,computed} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,notifyError} from '../lib/api.js'
import {money,typeName,categoryTone} from '../lib/format.js'
import StateBox from '../components/StateBox.vue'
import AppIcon from '../components/AppIcon.vue'
import BillDialog from '../components/BillDialog.vue'
import AnomalyDrawer from '../components/AnomalyDrawer.vue'
const route=useRoute(),router=useRouter(),loading=ref(false),error=ref(''),categories=ref([]),rows=ref([]),total=ref(0),page=ref(1),size=ref(10),dialog=ref(false),editing=ref(null),analysis=ref(false),billId=ref(null)
const filter=reactive({type:'',categoryId:null,dates:[],keyword:''}),names=computed(()=>Object.fromEntries(categories.value.map(c=>[c.id,c.name])))
let serial=0
async function load(){const n=++serial;loading.value=true;error.value='';try{const params={page:page.value,size:size.value};if(filter.type)params.type=filter.type;if(filter.categoryId)params.categoryId=filter.categoryId;if(filter.dates?.length===2){[params.from,params.to]=filter.dates}if(filter.keyword.trim())params.keyword=filter.keyword.trim();const [c,b]=await Promise.all([api.get('/categories'),api.get('/bills',{params})]);if(n===serial){categories.value=c;rows.value=b.records;total.value=b.total;if(!b.records.length&&page.value>1){page.value--;return load()}}}catch(e){if(n===serial)error.value=e.message}finally{if(n===serial)loading.value=false}}
function search(){page.value=1;load()}function reset(){Object.assign(filter,{type:'',categoryId:null,dates:[],keyword:''});search()}
function create(){editing.value=null;dialog.value=true}function edit(row){editing.value=row;dialog.value=true}
async function remove(row){try{await ElMessageBox.confirm(`确定删除“${row.description}”这笔${money(row.amount)}的账单？删除后统计和提醒会同步更新。`,'删除账单',{type:'warning',confirmButtonText:'确认删除',cancelButtonText:'取消'})}catch{return}try{await api.delete(`/bills/${row.id}`);ElMessage.success('账单已删除');await load()}catch(e){notifyError(e)}}
function inspect(row){billId.value=row.id;analysis.value=true}
watch(()=>route.query.new,v=>{if(v==='1'){create();router.replace({path:'/bills'})}},{immediate:true});onMounted(load)
</script><template><section class="panel" v-loading="loading"><div class="panel-heading"><div><h2>全部记录 <span class="count">{{total}}</span></h2><p>收入与支出，一目了然</p></div><el-button @click="create"><AppIcon name="Plus" :size="16"/>新增账单</el-button></div><div class="filter-bar"><el-input v-model="filter.keyword" placeholder="搜索账单描述" aria-label="搜索账单描述" clearable @keyup.enter="search"/><el-select v-model="filter.type" placeholder="全部收支" aria-label="收支筛选" clearable><el-option label="收入" value="INCOME"/><el-option label="支出" value="EXPENSE"/></el-select><el-select v-model="filter.categoryId" placeholder="全部分类" aria-label="分类筛选" clearable><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-date-picker v-model="filter.dates" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" aria-label="日期范围"/><el-button type="primary" plain @click="search">查询</el-button><el-button @click="reset">重置</el-button></div><StateBox :error="error" :empty="!loading&&!rows.length" title="没有找到相关账单" description="试试调整筛选条件，或记下第一笔收支。" @retry="load"><div class="table-scroll"><el-table :data="rows" row-key="id" style="width:100%"><el-table-column label="账单描述" min-width="200"><template #default="{row}"><div class="record-title"><span class="category-icon" :class="categoryTone(names[row.categoryId])"><AppIcon :name="row.type==='INCOME'?'TopRight':'ShoppingBag'" :size="18"/></span><span>{{row.description}}<small>#{{row.id}}</small></span></div></template></el-table-column><el-table-column label="分类" min-width="100"><template #default="{row}"><span class="category-tag">{{names[row.categoryId]||'—'}}</span></template></el-table-column><el-table-column label="日期" prop="billDate" min-width="112"/><el-table-column label="收支" width="76"><template #default="{row}">{{typeName(row.type)}}</template></el-table-column><el-table-column label="金额" min-width="138" align="right"><template #default="{row}"><span class="table-amount" :class="{income:row.type==='INCOME'}">{{row.type==='INCOME'?'+':'−'}}{{money(row.amount)}}</span></template></el-table-column><el-table-column label="操作" min-width="184" align="right"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button v-if="row.type==='EXPENSE'" link @click="inspect(row)">分析</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></div><div class="pagination"><span>共{{total}}笔记录</span><el-pagination v-model:current-page="page" v-model:page-size="size" :total="total" :page-sizes="[10,20,50]" layout="prev, pager, next, sizes" @current-change="load" @size-change="search"/></div></StateBox></section><BillDialog v-model="dialog" :record="editing" :categories="categories" @saved="load"/><AnomalyDrawer v-model="analysis" :bill-id="billId"/></template>
